{
  "PROP-57888860-inv-029": {
    "property_id": "PROP-57888860-inv-029",
    "audit_result": {
      "property_id": "PROP-57888860-inv-029",
      "classification": "vulnerability",
      "code_path": "beacon_chain/spec/peerdas_helpers.nim::get_data_column_sidecars::L275-276",
      "proof_trace": "Code adds entire cells/proofs arrays instead of selecting column-specific elements: uses cellsAndProofs[i].cells instead of cellsAndProofs[i].cells[column_index], causing each sidecar.column to contain NUMBER_OF_COLUMNS * blob_count cells instead of blob_count cells, violating len(sidecar.column) == len(kzg_commitments).",
      "attack_scenario": "Malicious block proposer or validator provides crafted CellsAndProofs that exploit the missing column index, causing data column sidecars with incorrect cell counts that fail validation at gossip recipients, leading to network-wide block propagation failure or consensus disruption.",
      "checklist_id": "PROP-57888860-inv-029"
    },
    "text": "Each sidecar must contain exactly one cell and one proof per blob in the block.",
    "assertion": "forall sidecar in sidecars: len(sidecar.column) == len(kzg_commitments) AND len(sidecar.kzg_proofs) == len(kzg_commitments)",
    "covers": "SG-003",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

for blbIdx, blob in blobs.pairs:
  let cellsAndProofs = computeCellsAndKzgProofs(blob)
  if cellsAndProofs.isErr:
    return err("Computing Extended Matrix: Issue computing cells and proofs")

  for i in 0..<fulu.CELLS_PER_EXT_BLOB:
    extended_matrix.add(MatrixEntry(
      cell: cellsAndProofs.get.cells[i],
      kzg_proof: cellsAndProofs.get.proofs[i],
      row_index: blbIdx.uint64,
      column_index: i.uint64
    ))

ok(extended_matrix)

